68: pub(crate) async fn run_with_request_telemetry<T, F, Fut>(
69:     policy: RetryPolicy,
70:     telemetry: Option<Arc<dyn RequestTelemetry>>,
71:     make_request: impl FnMut() -> Request,
72:     send: F,
73: ) -> Result<T, TransportError>
74: where
75:     T: WithStatus,
76:     F: Clone + Fn(Request) -> Fut,
77:     Fut: Future<Output = Result<T, TransportError>>,
78: {
79:     // Wraps `run_with_retry` to attach per-attempt request telemetry for both
80:     // unary and streaming HTTP calls.
81:     run_with_retry(policy, make_request, move |req, attempt| {
82:         let telemetry = telemetry.clone();
83:         let send = send.clone();
84:         async move {
85:             let start = Instant::now();
86:             let result = send(req).await;
87:             if let Some(t) = telemetry.as_ref() {
88:                 let (status, err) = match &result {
89:                     Ok(resp) => (Some(resp.status()), None),
90:                     Err(err) => (http_status(err), Some(err)),
91:                 };
92:                 t.on_request(attempt, status, err, start.elapsed());
93:             }
94:             result
95:         }
96:     })
97:     .await
98: }


